mapper.select:
SELECT FROM ( SELECT v.*, ROW_NUMBER() OVER ( PARTITION BY v.root_project_id ORDER BY v.tree_version DESC, v.id DESC ) AS scope_rank FROM proj_project_tree_version v WHERE v.tenant_id = #{query.tenantId} AND v.deleted = b'0' AND v.status = 'ACTIVE'
AND v.root_project_id IN #{rootId}
AND 1 = 0
) active_versions WHERE scope_rank = 1
